import { Edit3, Plus, Trash2, X } from 'lucide-react';
import type { AddressItem } from '../../account/model/accountTypes';

type Props = { addresses: AddressItem[]; selectedId: string; onSelect: (id: string) => void; onAdd: () => void; onEdit: (address: AddressItem) => void; onDelete: (id: string) => void; onClose: () => void; formatAddress: (address: AddressItem) => string };

export function AddressSelector({ addresses, selectedId, onSelect, onAdd, onEdit, onDelete, onClose, formatAddress }: Props) {
  return <div className="fixed inset-0 z-50 bg-black/50 flex items-end sm:items-center justify-center" dir="rtl" onClick={onClose}><div className="bg-white w-full sm:max-w-lg max-h-[90vh] overflow-auto rounded-t-2xl sm:rounded-2xl" onClick={(event) => event.stopPropagation()}><header className="flex items-center justify-between p-4 border-b"><h2 className="text-sm font-bold">آدرس‌ها</h2><button type="button" onClick={onClose} aria-label="بستن"><X className="w-4 h-4" /></button></header><div className="p-4 space-y-3">{addresses.map((address) => <article key={address.id} className={`border p-3 ${address.id === selectedId ? 'border-black' : 'border-neutral-200'}`}><button type="button" onClick={() => { onSelect(address.id); onClose(); }} className="w-full text-right"><strong className="text-xs">{address.title}</strong><p className="text-[11px] text-neutral-600 mt-1">{formatAddress(address)}</p><p className="text-[10px] text-neutral-500 mt-1">{address.recipientName} · {address.recipientPhone}</p></button><div className="flex gap-3 mt-2"><button type="button" onClick={() => onEdit(address)} className="text-[10px] inline-flex items-center gap-1"><Edit3 className="w-3 h-3" />ویرایش</button><button type="button" onClick={() => onDelete(address.id)} className="text-[10px] text-red-600 inline-flex items-center gap-1"><Trash2 className="w-3 h-3" />حذف</button></div></article>)}<button type="button" onClick={onAdd} className="w-full border border-dashed border-neutral-400 py-2 text-xs inline-flex justify-center gap-1"><Plus className="w-3.5 h-3.5" />افزودن آدرس</button></div></div></div>;
}
