import { Heart, ChevronLeft, Trash2 } from 'lucide-react';
import type { Product } from '../../../types';
import { ProductPrice, ResponsiveImage } from '../../../shared/ui';

type WishlistViewProps = { products: Product[]; onBack: () => void; onShop: () => void; onOpenProduct: (product: Product) => void; onRemove?: (product: Product) => void };

export function WishlistView({ products, onBack, onShop, onOpenProduct, onRemove }: WishlistViewProps) {
  return <div className="min-h-screen bg-white text-neutral-900 font-tommy" dir="rtl"><main className="max-w-[620px] mx-auto px-4 sm:px-6 pt-6 sm:pt-8 pb-24"><div className="flex items-center justify-between pb-4 border-b border-neutral-200/80 mb-6"><h2 className="text-[12.5px] font-bold">علاقه‌مندی‌ها ({products.length})</h2><button type="button" onClick={onBack} className="inline-flex items-center gap-1 text-[11px] text-neutral-600"><span>بازگشت</span><ChevronLeft className="w-4 h-4" /></button></div>{products.length === 0 ? <div className="py-16 text-center space-y-3 border border-neutral-200 bg-neutral-50/50"><Heart className="w-8 h-8 mx-auto text-neutral-400" /><h3 className="text-[12.5px] font-semibold">لیست علاقه‌مندی‌های شما خالی است</h3><p className="text-[11px] text-neutral-500">محصولات مورد علاقه‌تان را از کنار کارت محصولات ذخیره کنید.</p><button type="button" onClick={onShop} className="mt-3 px-5 py-2.5 bg-black text-white text-[11px]">مشاهده محصولات</button></div> : <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">{products.map((product) => <article key={product.id} className="border border-neutral-200/80 p-3 bg-white"><button type="button" onClick={() => onOpenProduct(product)} className="block w-full text-right"><div className="aspect-[3/4] bg-neutral-100 overflow-hidden mb-2"><ResponsiveImage src={product.image} alt={product.name} /></div><h4 className="text-[11px] font-medium line-clamp-1">{product.name}</h4><ProductPrice value={product.price} className="text-[10.5px] text-neutral-600" /></button>{onRemove && <button type="button" onClick={() => onRemove(product)} className="mt-2 inline-flex items-center gap-1 text-[10px] text-red-600"><Trash2 className="w-3 h-3" /> حذف</button>}</article>)}</div>}</main></div>;
}
