import { ChevronLeft, Package } from 'lucide-react';
import type { Product, UserOrder } from '../../../types';
import { formatTomanPrice, toPersianDigits } from '../../../utils/persianNumbers';

type OrdersViewProps = { orders: UserOrder[]; onBack: () => void; onShop: () => void; onOpenProduct: (product: Product) => void };

export function OrdersView({ orders, onBack, onShop, onOpenProduct }: OrdersViewProps) {
  return <div className="min-h-screen bg-white text-neutral-900 font-tommy" dir="rtl"><main className="max-w-[620px] mx-auto px-4 sm:px-6 pt-6 sm:pt-8 pb-24">
    <div className="flex items-center justify-between pb-4 border-b border-neutral-200/80 mb-6"><h2 className="text-[12.5px] font-bold">سفارش‌ها {orders.length > 0 && `(${toPersianDigits(orders.length)})`}</h2><button type="button" onClick={onBack} className="inline-flex items-center gap-1 text-[11px] text-neutral-600 hover:text-black"><span>بازگشت</span><ChevronLeft className="w-4 h-4" /></button></div>
    {orders.length === 0 ? <div className="py-16 text-center border border-neutral-200 bg-neutral-50/50 space-y-3"><Package className="w-8 h-8 mx-auto text-neutral-400" /><h3 className="text-[12.5px] font-semibold">سفارش فعالی در حال پردازش نیست</h3><p className="text-[11px] text-neutral-500">تمامی سفارش‌های ثبت‌شده پس از تحویل، کد رهگیری دریافت خواهند کرد.</p><button type="button" onClick={onShop} className="px-5 py-2.5 bg-black text-white text-[11px]">مرور محصولات</button></div> : <div className="space-y-4">{orders.map((order) => <article key={order.id} className="border border-neutral-200 rounded-xl p-3.5 space-y-3"><div className="flex items-center justify-between pb-2.5 border-b border-neutral-100"><span className="text-[10px] font-semibold bg-emerald-50 text-emerald-800 border border-emerald-200 px-2 py-0.5 rounded-full">{order.status}</span><span className="text-[10px] text-neutral-400">{toPersianDigits(order.date)}</span><span className="text-[11px] font-mono">#{order.trackingCode}</span></div><div className="flex flex-wrap gap-2 text-[10.5px] text-neutral-500"><span>روش ارسال: {order.deliveryMethod === 'courier' ? 'پیک' : 'پست'}</span><span>•</span><span>درگاه: {order.paymentGateway === 'zarinpal' ? 'زرین‌پال' : 'زیبال'}</span><span>•</span><span>گیرنده: {order.recipient.name}</span></div><div className="flex gap-2 overflow-x-auto">{order.items.map((item, index) => <button type="button" key={`${order.id}-${index}`} onClick={() => onOpenProduct(item.product)} className="flex items-center gap-2 border border-neutral-150 bg-neutral-50 p-1.5 rounded-lg shrink-0 text-right"><img src={item.product.image} alt={item.product.name} className="w-10 h-12 object-cover rounded" /><span className="text-[10px]"><strong className="block max-w-[120px] truncate">{item.product.name}</strong><span className="text-neutral-500">سایز {toPersianDigits(item.selectedSize)} • {toPersianDigits(item.quantity)} عدد</span></span></button>)}</div><div className="flex items-center justify-between pt-2.5 border-t border-neutral-100 text-[11px]"><span className="text-neutral-500">تعداد اقلام: {toPersianDigits(order.items.reduce((sum, item) => sum + item.quantity, 0))}</span><strong>{formatTomanPrice(order.finalTotal)}</strong></div></article>)}</div>}
  </main></div>;
}
