import { ChevronLeft } from 'lucide-react';
import { FormField } from '../../../shared/ui';
import { toPersianDigits } from '../../../utils/persianNumbers';

type PersonalInfoViewProps = { userPhone: string; firstName: string; lastName: string; nationalCode: string; email: string; onFirstNameChange: (value: string) => void; onLastNameChange: (value: string) => void; onNationalCodeChange: (value: string) => void; onEmailChange: (value: string) => void; onSave: (event: React.FormEvent) => void; onBack: () => void };

export function PersonalInfoView({ userPhone, firstName, lastName, nationalCode, email, onFirstNameChange, onLastNameChange, onNationalCodeChange, onEmailChange, onSave, onBack }: PersonalInfoViewProps) {
  return <div className="min-h-screen bg-white text-neutral-900 font-tommy" dir="rtl"><main className="max-w-[620px] mx-auto px-4 sm:px-6 pt-6 sm:pt-8 pb-24"><div className="flex items-center justify-between pb-4 border-b border-neutral-200/80 mb-6"><h2 className="text-[12.5px] font-bold">اطلاعات حساب کاربری</h2><button type="button" onClick={onBack} className="inline-flex items-center gap-1 text-[11px] text-neutral-600"><span>بازگشت</span><ChevronLeft className="w-4 h-4" /></button></div><form onSubmit={onSave} className="space-y-4"><div className="grid grid-cols-1 sm:grid-cols-2 gap-3"><FormField id="profile-first-name" label="نام" value={firstName} onChange={(event) => onFirstNameChange(event.target.value)} /><FormField id="profile-last-name" label="نام خانوادگی" value={lastName} onChange={(event) => onLastNameChange(event.target.value)} /></div><FormField id="profile-phone" label="شماره موبایل" value={toPersianDigits(userPhone)} disabled readOnly /><FormField id="profile-national-code" label="کد ملی (اختیاری)" value={nationalCode} maxLength={10} onChange={(event) => onNationalCodeChange(event.target.value)} /><FormField id="profile-email" label="ایمیل (اختیاری)" type="email" dir="ltr" value={email} onChange={(event) => onEmailChange(event.target.value)} /><div className="pt-3 flex items-center gap-2"><button type="submit" className="flex-1 h-10 bg-[#171717] text-white text-[11.5px]">ذخیره تغییرات</button><button type="button" onClick={onBack} className="h-10 px-5 border border-neutral-200 text-neutral-700 text-[11.5px]">انصراف</button></div></form></main></div>;
}
