import { ShieldCheck } from 'lucide-react';
import { formatTomanPrice } from '../../../utils/persianNumbers';

type OrderSummaryProps = { subtotal: number; deliveryCost: number; discountAmount: number; discountCode?: string; finalTotal: number; step: 'shipping' | 'payment'; canContinue: boolean; isFinalizing: boolean; gateway: string; onContinue: () => void; onFinalize: () => void };

export function OrderSummary({ subtotal, deliveryCost, discountAmount, discountCode, finalTotal, step, canContinue, isFinalizing, gateway, onContinue, onFinalize }: OrderSummaryProps) {
  return <><div className="py-2.5 space-y-1.5 text-[11px]"><div className="flex justify-between text-neutral-600"><span>مجموع اقلام</span><span className="font-semibold text-neutral-900">{formatTomanPrice(subtotal)}</span></div><div className="flex justify-between text-neutral-600"><span>هزینه ارسال</span><span className="font-semibold text-neutral-900">{formatTomanPrice(deliveryCost)}</span></div>{discountAmount > 0 && <div className="flex justify-between text-emerald-700 font-semibold"><span>تخفیف ({discountCode})</span><span>- {formatTomanPrice(discountAmount)}</span></div>}<div className="flex justify-between text-xs sm:text-[13px] font-bold text-neutral-900 pt-2 border-t border-neutral-200"><span>مبلغ قابل پرداخت</span><span>{formatTomanPrice(finalTotal)}</span></div></div>{step === 'shipping' ? <button type="button" onClick={onContinue} disabled={!canContinue} className="w-full mt-3 py-2.5 bg-neutral-900 text-white text-xs font-bold disabled:opacity-50">پرداخت سفارش</button> : <button type="button" onClick={onFinalize} disabled={isFinalizing} className="w-full mt-3 py-2.5 bg-neutral-900 text-white text-xs font-bold disabled:opacity-50">{isFinalizing ? 'در حال اتصال به درگاه...' : `پرداخت با ${gateway}`}</button>}<div className="flex items-center justify-center gap-1.5 text-[9px] text-neutral-400 pt-2.5"><ShieldCheck className="w-3 h-3" /><span>ضمانت بازگشت و پشتیبانی لنگه</span></div></>;
}
