import { X } from 'lucide-react';
import type { AddressItem } from '../../account/model/accountTypes';

type Props = { form: Omit<AddressItem, 'id'>; editing: boolean; onChange: (form: Omit<AddressItem, 'id'>) => void; onSave: (event: React.FormEvent) => void; onClose: () => void; provinces: Record<string, string[]> };

export function AddressForm({ form, editing, onChange, onSave, onClose, provinces }: Props) {
  const update = (key: keyof Omit<AddressItem, 'id'>, value: string | boolean) => onChange({ ...form, [key]: value });
  return <div className="fixed inset-0 z-50 bg-black/50 flex items-end sm:items-center justify-center" dir="rtl" onClick={onClose}><div className="bg-white w-full sm:max-w-lg max-h-[90vh] overflow-auto rounded-t-2xl sm:rounded-2xl p-5" onClick={(event) => event.stopPropagation()}><header className="flex items-center justify-between mb-4"><h2 className="text-sm font-bold">{editing ? 'ویرایش نشانی تحویل' : 'افزودن نشانی جدید'}</h2><button type="button" onClick={onClose} aria-label="بستن"><X className="w-4 h-4" /></button></header><form onSubmit={onSave} className="space-y-3 text-xs">{(['title','recipientName','fullAddress','postalCode','plaque','unit','recipientPhone'] as const).map((key) => <label key={key} className="block"><span className="text-neutral-600">{key}</span><input value={form[key]} onChange={(event) => update(key, event.target.value)} className="mt-1 w-full h-9 border border-neutral-300 px-2" /></label>)}<div className="grid grid-cols-2 gap-2"><select value={form.province} onChange={(event) => update('province', event.target.value)} className="h-9 border px-2">{Object.keys(provinces).map((province) => <option key={province}>{province}</option>)}</select><select value={form.city} onChange={(event) => update('city', event.target.value)} className="h-9 border px-2">{(provinces[form.province] || []).map((city) => <option key={city}>{city}</option>)}</select></div><label className="flex items-center gap-2"><input type="checkbox" checked={form.isDefault} onChange={(event) => update('isDefault', event.target.checked)} /> آدرس پیش‌فرض</label><button type="submit" className="w-full py-2 bg-black text-white">ذخیره</button></form></div></div>;
}
